const listUserNamespaces = `-- name: ListUserNamespaces :many
WITH user_ns AS (
    -- All roles the user holds in each namespace (owner role first).
    SELECT
        rb.namespace_id,
        array_agg(r.name ORDER BY rb.is_owner DESC, r.name ASC)::TEXT[] AS role_names,
        array_agg(r.display_name ORDER BY rb.is_owner DESC, r.name ASC)::TEXT[] AS role_display_names,
        min(rb.created_at)::TIMESTAMPTZ AS joined_at
    FROM role_bindings rb
    JOIN roles r ON r.id = rb.role_id
    WHERE rb.user_id = $9 AND rb.scope = 'namespace'
    GROUP BY rb.namespace_id
)
SELECT ns.id, ns.name, ns.display_name, ns.description, ns.workspace_id, ns.owner_id,
       ns.visibility, ns.max_members, ns.status, ns.created_at, ns.updated_at,
       u.username AS owner_username,
       w.name AS workspace_name,
       (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'namespace' AND rb2.namespace_id = ns.id) AS member_count,
       un.role_names, un.role_display_names, un.joined_at
FROM user_ns un
JOIN namespaces ns ON ns.id = un.namespace_id
JOIN users u ON ns.owner_id = u.id
JOIN workspaces w ON ns.workspace_id = w.id
WHERE ($1::VARCHAR IS NULL OR ns.status = ANY(string_to_array($1::VARCHAR, ',')))
  AND ($2::VARCHAR IS NULL OR ns.visibility = $2)
  AND ($3::BIGINT IS NULL OR ns.workspace_id = $3)
  AND ($4::VARCHAR IS NULL OR (
       ns.name ILIKE '%' || $4 || '%'
       OR ns.display_name ILIKE '%' || $4 || '%'
       OR array_to_string(un.role_names, ',') ILIKE '%' || $4 || '%'
       OR array_to_string(un.role_display_names, ',') ILIKE '%' || $4 || '%'
  ))
ORDER BY
    CASE WHEN $5::VARCHAR = 'name' AND $6::VARCHAR = 'asc' THEN ns.name END ASC,
    CASE WHEN $5::VARCHAR = 'name' AND $6::VARCHAR = 'desc' THEN ns.name END DESC,
    CASE WHEN $5::VARCHAR = 'display_name' AND $6::VARCHAR = 'asc' THEN ns.display_name END ASC,
    CASE WHEN $5::VARCHAR = 'display_name' AND $6::VARCHAR = 'desc' THEN ns.display_name END DESC,
    CASE WHEN $5::VARCHAR = 'member_count' AND $6::VARCHAR = 'asc' THEN (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'namespace' AND rb2.namespace_id = ns.id) END ASC,
    CASE WHEN $5::VARCHAR = 'member_count' AND $6::VARCHAR = 'desc' THEN (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'namespace' AND rb2.namespace_id = ns.id) END DESC,
    CASE WHEN $5::VARCHAR = 'role_name' AND $6::VARCHAR = 'asc' THEN un.role_names[1] END ASC,
    CASE WHEN $5::VARCHAR = 'role_name' AND $6::VARCHAR = 'desc' THEN un.role_names[1] END DESC,
    CASE WHEN $5::VARCHAR = 'created_at' AND $6::VARCHAR = 'asc' THEN ns.created_at END ASC,
    CASE WHEN $5::VARCHAR = 'created_at' AND $6::VARCHAR = 'desc' THEN ns.created_at END DESC,
    CASE WHEN $5::VARCHAR = 'updated_at' AND $6::VARCHAR = 'asc' THEN ns.updated_at END ASC,
    CASE WHEN $5::VARCHAR = 'updated_at' AND $6::VARCHAR = 'desc' THEN ns.updated_at END DESC,
    CASE WHEN $5::VARCHAR = 'joined_at' AND $6::VARCHAR = 'asc' THEN un.joined_at END ASC,
    CASE WHEN $5::VARCHAR = 'joined_at' AND $6::VARCHAR = 'desc' THEN un.joined_at END DESC,
    un.joined_at DESC
LIMIT $8::INT
OFFSET $7::INT
`

