const listUserWorkspaces = `-- name: ListUserWorkspaces :many
WITH user_ws AS (
    -- All roles the user holds in each workspace (owner role first), not
    -- just one: a user may hold several roles in the same scope.
    SELECT
        rb.workspace_id,
        array_agg(r.name ORDER BY rb.is_owner DESC, r.name ASC)::TEXT[] AS role_names,
        array_agg(r.display_name ORDER BY rb.is_owner DESC, r.name ASC)::TEXT[] AS role_display_names,
        min(rb.created_at)::TIMESTAMPTZ AS joined_at
    FROM role_bindings rb
    JOIN roles r ON r.id = rb.role_id
    WHERE rb.user_id = $7 AND rb.scope = 'workspace'
    GROUP BY rb.workspace_id
)
SELECT ws.id, ws.name, ws.display_name, ws.description, ws.owner_id, ws.status,
       ws.created_at, ws.updated_at,
       u.username AS owner_username,
       (SELECT count(*) FROM namespaces n WHERE n.workspace_id = ws.id) AS namespace_count,
       (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'workspace' AND rb2.workspace_id = ws.id) AS member_count,
       uw.role_names, uw.role_display_names, uw.joined_at
FROM user_ws uw
JOIN workspaces ws ON ws.id = uw.workspace_id
JOIN users u ON ws.owner_id = u.id
WHERE ($1::VARCHAR IS NULL OR ws.status = ANY(string_to_array($1::VARCHAR, ',')))
  AND ($2::VARCHAR IS NULL OR (
       ws.name ILIKE '%' || $2 || '%'
       OR ws.display_name ILIKE '%' || $2 || '%'
       OR array_to_string(uw.role_names, ',') ILIKE '%' || $2 || '%'
       OR array_to_string(uw.role_display_names, ',') ILIKE '%' || $2 || '%'
  ))
ORDER BY
    CASE WHEN $3::VARCHAR = 'name' AND $4::VARCHAR = 'asc' THEN ws.name END ASC,
    CASE WHEN $3::VARCHAR = 'name' AND $4::VARCHAR = 'desc' THEN ws.name END DESC,
    CASE WHEN $3::VARCHAR = 'display_name' AND $4::VARCHAR = 'asc' THEN ws.display_name END ASC,
    CASE WHEN $3::VARCHAR = 'display_name' AND $4::VARCHAR = 'desc' THEN ws.display_name END DESC,
    CASE WHEN $3::VARCHAR = 'namespace_count' AND $4::VARCHAR = 'asc' THEN (SELECT count(*) FROM namespaces n WHERE n.workspace_id = ws.id) END ASC,
    CASE WHEN $3::VARCHAR = 'namespace_count' AND $4::VARCHAR = 'desc' THEN (SELECT count(*) FROM namespaces n WHERE n.workspace_id = ws.id) END DESC,
    CASE WHEN $3::VARCHAR = 'member_count' AND $4::VARCHAR = 'asc' THEN (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'workspace' AND rb2.workspace_id = ws.id) END ASC,
    CASE WHEN $3::VARCHAR = 'member_count' AND $4::VARCHAR = 'desc' THEN (SELECT count(DISTINCT rb2.user_id) FROM role_bindings rb2 WHERE rb2.scope = 'workspace' AND rb2.workspace_id = ws.id) END DESC,
    CASE WHEN $3::VARCHAR = 'role_name' AND $4::VARCHAR = 'asc' THEN uw.role_names[1] END ASC,
    CASE WHEN $3::VARCHAR = 'role_name' AND $4::VARCHAR = 'desc' THEN uw.role_names[1] END DESC,
    CASE WHEN $3::VARCHAR = 'created_at' AND $4::VARCHAR = 'asc' THEN ws.created_at END ASC,
    CASE WHEN $3::VARCHAR = 'created_at' AND $4::VARCHAR = 'desc' THEN ws.created_at END DESC,
    CASE WHEN $3::VARCHAR = 'updated_at' AND $4::VARCHAR = 'asc' THEN ws.updated_at END ASC,
    CASE WHEN $3::VARCHAR = 'updated_at' AND $4::VARCHAR = 'desc' THEN ws.updated_at END DESC,
    CASE WHEN $3::VARCHAR = 'joined_at' AND $4::VARCHAR = 'asc' THEN uw.joined_at END ASC,
    CASE WHEN $3::VARCHAR = 'joined_at' AND $4::VARCHAR = 'desc' THEN uw.joined_at END DESC,
    uw.joined_at DESC
LIMIT $6::INT
OFFSET $5::INT
`

